Проблема в том, что вы используете мировые координаты вместо локальных относительно камеры. Вот исправленный код:

```cpp
void addPlayersToRadar(Player * player) {
    Vector3 myPos = GetPosition(myPlayer);
    Vector3 playerPos = player->position;

    // Получаем поворот камеры
    Quaternion cameraRotation = GetRotation(get_main());

    // Вычисляем вектор от игрока к цели
    Vector3 directionToPlayer = playerPos - myPos;

    // ВАЖНО: Инвертируем поворот камеры для корректной трансформации
    Quaternion inverseCameraRotation = Inverse(cameraRotation);

    // Преобразуем в локальное пространство камеры
    Vector3 localPosition = inverseCameraRotation * directionToPlayer;

    // Масштабируем для радара (например, 1 метр = 1 пиксель)
    float radarScale = 1.0f; // Настройте по необходимости
    float radarX = localPosition.x * radarScale;
    float radarZ = localPosition.z * radarScale;

    // Ограничиваем радиус радара
    float maxRadarDistance = 180.0f;
    float distanceOnRadar = sqrt(radarX * radarX + radarZ * radarZ);

    if (distanceOnRadar > maxRadarDistance) {
        float scale = maxRadarDistance / distanceOnRadar;
        radarX *= scale;
        radarZ *= scale;
    }

    // Отрисовываем точку (Z идет вперед, X - вправо)
    bg->AddCircleFilled(
        {radar_center.x + radarX, radar_center.y - radarZ}, // Минус Z, так как Y направлена вниз
        5, 
        ImColor(255, 0, 0, 255)
    );
}
```

**Ключевые изменения:**

1. **Inverse(cameraRotation)** - инвертируем поворот камеры для корректной трансформации
2. **Правильная последовательность**: сначала вычисляем направление, потом трансформируем
3. **Корректное масштабирование** радиуса радара
4. **Минус перед Z** при отрисовке (так как Y в ImGui направлена вниз)

**Если функция Inverse недоступна:**

```cpp
// Альтернативный способ без Inverse
Vector3 forward = cameraRotation * Vector3(0, 0, 1);
Vector3 right = cameraRotation * Vector3(1, 0, 0);

Vector3 directionToPlayer = playerPos - myPos;

float radarX = Vector3::Dot(directionToPlayer, right);
float radarZ = Vector3::Dot(directionToPlayer, forward);

// Далее такое же ограничение и отрисовка
```

